// Turn the comma/line separated list of websites into one clean item per domain.
const cfg = $input.first().json;

const cleaned = [];
const bad = [];
for (const raw of String(cfg.domains || '').split(/[\s,;]+/)) {
  const entry = raw.trim();
  if (!entry) continue;
  const host = entry.toLowerCase().replace(/^[a-z]+:\/\//, '').replace(/[/?#].*$/, '').replace(/:\d+$/, '').replace(/\.$/, '');
  if (!/^(?=.{1,253}$)([a-z0-9*]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/.test(host) || host.includes('*')) {
    bad.push(entry);
    continue;
  }
  if (!cleaned.includes(host)) cleaned.push(host);
}

if (!cleaned.length) {
  throw new Error('No valid website in "domains". Write them separated by commas, for example: example.com, my-shop.com');
}
if (bad.length) {
  // Keep going with the valid ones, but make the mistake visible in the execution log.
  console.log(`Ignored entries that are not domain names: ${bad.join(', ')}`);
}

return cleaned.slice(0, 50).map((domain) => ({ json: { domain, ignored_entries: bad.join(', ') } }));

// Read each certificate answer, decide what deserves an alert and build ONE Telegram message.
const cfg = $('Settings').first().json;
const domains = $('List domains').all();
const store = $getWorkflowStaticData('global');
const state = store.cert_state || {};

// Alert thresholds in days, e.g. "30, 14, 7, 3, 1".
const thresholds = String(cfg.alert_days_before === undefined ? '' : cfg.alert_days_before)
  .split(',').map((x) => Number(x.trim())).filter((x) => Number.isFinite(x) && x > 0)
  .sort((a, b) => b - a);
if (!thresholds.length) {
  throw new Error('"alert_days_before" must list numbers of days, for example 30, 14, 7, 3, 1');
}
const reportAll = cfg.report_all === true;
const today = new Date().toISOString().slice(0, 10);
const DAY = 24 * 3600 * 1000;

const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Does a name from the certificate (exact or *.wildcard) cover this domain?
const covers = (pattern, domain) => {
  const p = pattern.toLowerCase().replace(/^dns:/, '').trim();
  if (p === domain) return true;
  if (!p.startsWith('*.')) return false;
  const rest = p.slice(1); // ".example.com"
  return domain.endsWith(rest) && !domain.slice(0, -rest.length).includes('.') && domain.length > rest.length;
};

const alerts = [];
const overview = [];

$input.all().forEach((item, i) => {
  const src = domains[item.pairedItem && item.pairedItem.item !== undefined ? item.pairedItem.item : i];
  if (!src) return;
  const domain = src.json.domain;
  const st = state[domain] || {};
  const j = item.json || {};
  const cert = j.certificate;

  // 1) Could we read a certificate?
  if (j.status !== 'OK' || !cert || !cert.valid_to) {
    const unresolved = j.status === 'HOST_NOT_RESOLVED';
    st.failures = (st.failures || 0) + 1;
    const reason = unresolved ? 'the domain does not resolve (typo?)' : `no certificate could be read${j.status ? ` (${j.status})` : ''}`;
    // A typo is reported at once; a temporary hiccup only after two failed checks in a row.
    if (reportAll || (unresolved && st.failures === 1) || (!unresolved && st.failures === 2)) {
      alerts.push({ rank: 1, icon: '❓', domain, text: `cannot check: ${reason}` });
    }
    overview.push({ domain, text: `cannot check: ${reason}` });
    state[domain] = st;
    return;
  }
  st.failures = 0;

  const validTo = Date.parse(cert.valid_to);
  const daysLeft = Math.floor((validTo - Date.now()) / DAY);
  const until = new Date(validTo).toISOString().slice(0, 10);
  const names = [...new Set([cert.issued_to, ...(cert.alternate_names || [])].filter(Boolean).map((n) => n.replace(/^dns:/i, '')))];
  const matches = names.some((n) => covers(n, domain));
  const issuer = cert.issued_by ? ` · issued by ${cert.issued_by}` : '';

  // 2) Name mismatch: reported once, again only if it comes back after being fixed.
  if (!matches) {
    if (reportAll || !st.mismatch) {
      alerts.push({ rank: 2, icon: '⚠️', domain, text: `the certificate is not valid for this name (it covers ${names.slice(0, 3).join(', ')})` });
    }
    st.mismatch = true;
  } else {
    st.mismatch = false;
  }

  // 3) Expiry.
  let label;
  if (daysLeft < 0) {
    label = `expired ${-daysLeft} day${daysLeft === -1 ? '' : 's'} ago (${until})`;
    // An expired certificate is repeated once a day until it is renewed.
    if (reportAll || st.expired_day !== today) {
      alerts.push({ rank: 0, icon: '🔴', domain, text: label + issuer });
    }
    st.expired_day = today;
    st.threshold = 0;
  } else {
    label = `expires in ${daysLeft} day${daysLeft === 1 ? '' : 's'} (${until})`;
    const crossed = thresholds.filter((t) => daysLeft <= t).pop(); // smallest threshold already reached
    if (crossed === undefined) {
      st.threshold = null; // renewed: alerts start over for the next cycle
      st.expired_day = null;
      if (reportAll && matches) alerts.push({ rank: 5, icon: '🟢', domain, text: label });
    } else {
      if (reportAll || st.threshold !== crossed) {
        const urgent = crossed <= Math.min(7, thresholds[0]);
        alerts.push({ rank: urgent ? 0.5 : 3, icon: urgent ? '🟠' : '🟡', domain, text: label + issuer });
      }
      st.threshold = crossed;
    }
  }
  overview.push({ domain, text: label });
  state[domain] = st;
});

// Forget domains that are no longer in the list.
const current = new Set(domains.map((d) => d.json.domain));
for (const k of Object.keys(state)) if (!current.has(k)) delete state[k];
store.cert_state = state;

if (!alerts.length) return [];

alerts.sort((a, b) => a.rank - b.rank || a.domain.localeCompare(b.domain));
const title = reportAll ? '🔒 <b>SSL certificate report</b>' : `🔒 <b>SSL certificate alert${alerts.length > 1 ? 's' : ''}</b> (${alerts.length})`;
const lines = [];
let used = title.length;
for (const a of alerts) {
  const line = `\n${a.icon} <b>${esc(a.domain)}</b>\n${esc(a.text)}\n`;
  if (used + line.length > 3800) break;
  lines.push(line);
  used += line.length;
}
const more = alerts.length - lines.length;
const message = title + '\n' + lines.join('') + (more > 0 ? `\n…and ${more} more (see the n8n execution).` : '');

return [{ json: { message, alerts: alerts.length, checked: domains.length } }];
